-- ============================================================================
-- DDL Schema Script for Multi-Code Vendor Grouping (PURSYS.VENDORS_CODE)
-- Purpose: Group multiple VND_CODE records under 1 Corporate Vendor Entity
--          for Shared E-SCM Portal Accounts & Approved List Reporting
-- ============================================================================

CREATE TABLE PURSYS.VENDORS_CODE (
    ID              NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    GROUP_ID        VARCHAR2(20)      NOT NULL,
    GROUP_NAME      VARCHAR2(200)     NOT NULL,
    VND_CODE        VARCHAR2(10)      NOT NULL,
    IS_PRIMARY      VARCHAR2(1)       DEFAULT 'N' NOT NULL,
    STATUS          VARCHAR2(10)      DEFAULT 'ACTIVE' NOT NULL,
    REMARK          VARCHAR2(500),
    CREATE_AT       TIMESTAMP         DEFAULT CURRENT_TIMESTAMP,
    CREATE_BY       VARCHAR2(50),
    UPDATE_AT       TIMESTAMP,
    UPDATE_BY       VARCHAR2(50),
    CONSTRAINT UQ_VENDORS_CODE_VNDCODE UNIQUE (VND_CODE),
    CONSTRAINT FK_VENDORS_CODE_VENDORS FOREIGN KEY (VND_CODE)
        REFERENCES PURSYS.VENDORS (VND_CODE)
);

CREATE INDEX PURSYS.IX_VENDORS_CODE_GROUP ON PURSYS.VENDORS_CODE (GROUP_ID);
